corrected_code:
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"myapp/middleware"
	"myapp/payout"
)

func RegisterWalletRoutes(r *gin.Engine, svc *payout.WalletService) {
	walletGroup := r.Group("/wallet")
	walletGroup.Use(middleware.WalletAuthMiddleware())

	walletGroup.POST("/payout", func(c *gin.Context) {
		var req payout.PayoutRequest
		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		authAccount := c.GetString("authenticated_account_id")
		if authAccount != req.AccountID {
			c.JSON(http.StatusForbidden, gin.H{"error": "Unauthorized account payout"})
			return
		}
		result, err := svc.Disburse(c.Request.Context(), authAccount, req.Amount)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, result)
	})
}
